    private static AdvancementHolder buildArmor(String location, com.binaris.wizardry.content.advancement.WizardryContainerTrigger container, AdvancementHolder parent, Item display, Component name, Component desc, Collection<Item> items, Consumer<AdvancementHolder> consumer, ExistingFileHelper existingFileHelper) {
        Advancement.Builder builder = Advancement.Builder.advancement().parent(parent).display(display, name, desc, null, AdvancementType.GOAL, true, true, false).rewards(AdvancementRewards.EMPTY);

        for (Item item : items) {
            String itemName = item.getDefaultInstance().getItem().toString().replace("ebwizardry:", "");
            builder.addCriterion(itemName, container.forItem(ItemPredicate.Builder.item().of(item).build()));
        }

        builder.requirements(AdvancementRequirements.Strategy.AND);
        return builder.save(consumer, WizardryMainMod.location(location), existingFileHelper);
    }

    private static LocationPredicate.Builder inStructure(HolderLookup.Provider registries, ResourceKey<Structure> key) {
        return LocationPredicate.Builder.inStructure(registries.lookupOrThrow(Registries.STRUCTURE).getOrThrow(key));
    }

