        AdvancementHolder battlemage = buildArmor("battlemage", EBAdvancementTriggers.ARCANE_WORKBENCH, armorSet, EBItems.BATTLEMAGE_BOOTS.get(), Component.translatable("advancement.ebwizardry.battlemage"), Component.translatable("advancement.ebwizardry.battlemage.desc"), BATTLEMAGE_ITEMS, consumer, existingFileHelper);
